            next_sep_col = sep_cols[c_idx+1]
            num_cols = next_sep_col - col_start
        else:
            num_cols = len(grid[0]) - col_start

        # Safety check
        num_cols = min(num_cols, 5)

        print(f"Col group {c_idx}:")
        for dr in range(num_rows):
            row_vals = []
            for dc in range(min(num_cols, 5)):
                val = grid[row_start + dr][col_start + dc]
                if val != 5:
                    row_vals.append(str(val))
                else:
                    row_vals.append('.')
            print("  ", "".join(row_vals))

